package com.rodrigosambade.dragdropcontent;
import android.app.*; import android.os.*; import android.content.*; import android.view.*; import android.widget.*; import androidx.core.view.*;
public class MainActivity extends Activity { private EditText target; private TextView log;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,32,32,32);TextView source=new TextView(this);source.setText("Long-press and drag this rich text payload");source.setPadding(20,30,20,30);source.setOnLongClickListener(v->{ClipData clip=ClipData.newPlainText("demo","Dragged text from the source view");v.startDragAndDrop(clip,new View.DragShadowBuilder(v),null,View.DRAG_FLAG_GLOBAL);return true;});l.addView(source);target=new EditText(this);target.setHint("Drop/paste/share text here");l.addView(target);log=new TextView(this);l.addView(log);Button share=new Button(this);share.setText("Share target text");share.setOnClickListener(v->share());l.addView(share);setContentView(l);setupReceive();handleIntent(getIntent());}
 private void setupReceive(){ViewCompat.setOnReceiveContentListener(target,new String[]{"text/*"},(view,payload)->{ClipData clip=payload.getClip();StringBuilder b=new StringBuilder();for(int i=0;i<clip.getItemCount();i++){CharSequence t=clip.getItemAt(i).coerceToText(this);if(t!=null)b.append(t).append('\n');}target.append(b.toString());log.setText("Consumed "+clip.getItemCount()+" item(s) through receive-content");return null;});target.setOnDragListener((v,e)->{if(e.getAction()==DragEvent.ACTION_DROP){ClipData clip=e.getClipData();for(int i=0;i<clip.getItemCount();i++)target.append(String.valueOf(clip.getItemAt(i).coerceToText(this)));return true;}return e.getAction()!=DragEvent.ACTION_DRAG_ENDED;});}
 private void handleIntent(Intent i){if(Intent.ACTION_SEND.equals(i.getAction())){CharSequence t=i.getCharSequenceExtra(Intent.EXTRA_TEXT);if(t!=null)target.setText(t);}}
 private void share(){Intent s=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,target.getText().toString());startActivity(Intent.createChooser(s,"Share content"));}
}
